import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().runProgram();
    }

    void runProgram() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < k; i++) {
            base[in.nextInt()] = 1;
        }
        int[] ans = new int[]{1};
        int exp = n / 2;
        while (true) {
            if ((exp & 1) == 1) {
                ans = multiply(ans, base, MOD);
            }
            exp >>>= 1;
            if (exp == 0) break;
            base = multiply(base, base, MOD);
        }
        long sum = 0;
        for (int x : ans) {
            sum = (sum + (long)x * x) % MOD;
        }
        out.println(sum);
        out.close();
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int needed = a.length + b.length - 1;
        int size = 1;
        while (size < needed) size <<= 1;

        double[] ar = new double[size];
        double[] ai = new double[size];
        for (int i = 0; i < a.length; i++) {
            long val = ((long)a[i] % mod + mod) % mod;
            ar[i] = val & 0x7FFF;
            ai[i] = val >>> 15;
        }

        fft(ar, ai, false);

        double[] br = new double[size];
        double[] bi = new double[size];
        if (a == b) {
            System.arraycopy(ar, 0, br, 0, size);
            System.arraycopy(ai, 0, bi, 0, size);
        } else {
            for (int i = 0; i < b.length; i++) {
                long val = ((long)b[i] % mod + mod) % mod;
                br[i] = val & 0x7FFF;
                bi[i] = val >>> 15;
            }
            fft(br, bi, false);
        }

        double[] cr = new double[size];
        double[] ci = new double[size];
        double factor = 0.25 / size;

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double A1r = ar[i] + ar[j];
            double A1i = ai[i] - ai[j];
            double A2r = ai[i] + ai[j];
            double A2i = ar[j] - ar[i];

            double B1r = (br[i] + br[j]) * factor;
            double B1i = (bi[i] - bi[j]) * factor;
            double B2r = (bi[i] + bi[j]) * factor;
            double B2i = (br[j] - br[i]) * factor;

            cr[i] = A1r * B1r - A1i * B1i - A2r * B2i - A2i * B2r;
            ci[i] = A1r * B1i + A1i * B1r + A2r * B2r - A2i * B2i;
        }

        fft(cr, ci, true);

        int[] res = new int[needed];
        for (int i = 0; i < needed; i++) {
            long real = Math.round(cr[i]);
            long imag = Math.round(ci[i]);
            res[i] = (int)((real + ((imag % mod) << 15)) % mod);
        }
        return res;
    }

    void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            while ((j & bit) != 0) {
                j ^= bit;
                bit >>= 1;
            }
            j ^= bit;
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosines = new double[half];
            double[] sines = new double[half];
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosines[i] = Math.cos(i * angle);
                sines[i] = Math.sin(i * angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int k = 0; k < half; k++) {
                    double ur = re[i + k];
                    double ui = im[i + k];
                    double vr = re[i + k + half] * cosines[k] - im[i + k + half] * sines[k];
                    double vi = re[i + k + half] * sines[k] + im[i + k + half] * cosines[k];

                    re[i + k] = ur + vr;
                    im[i + k] = ui + vi;
                    re[i + k + half] = ur - vr;
                    im[i + k + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int read() {
            if (len == -1) throw new InputMismatchException();
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buffer); } catch (IOException e) { throw new InputMismatchException(); }
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int num = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                num = num * 10 + c - '0';
                c = read();
            }
            return num * sign;
        }
    }
}
